from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1]
models={}
labels={
 'annulus_winding_m1':('円環：巻き数 −1','内周・外周の端点を固定し、基準seamを負方向に横断する。'),
 'annulus_winding_p0':('円環：巻き数 0','同じ二端点を持つが、seamを横断しない。'),
 'annulus_winding_p1':('円環：巻き数 +1','同じ二端点を持ち、seamを正方向に横断する。'),
 'torus_three_crossings':('トーラス：三交点とD₀','両cycleは x₁⁺ → x₂⁻ → x₃⁺。黄色は幾何的な埋込み円板。保存方向のままではKoda joiningではない。'),
 'torus_parallel_zero_crossings':('トーラス：無交点の二曲線','交点列が空でも、二本の曲線と二つの環状領域を保持する。'),
 'nested_zero_crossings':('円板：二つの入れ子','contractible curveを削除しない。補領域は円環・円環・円板。'),
 'torus_mer_lon':('トーラス：meridian / longitude','補領域は開円板だが、閉包の境界は反復する。閉じた埋込み円板という判定はfalse。')}
for k,(title,description) in labels.items():
 d=json.loads((ROOT/'examples'/f'{k}.json').read_text());r=json.loads((ROOT/'artifacts'/f'{k}.report.json').read_text())
 models[k]={'title':title,'description':description,'svg':(ROOT/'artifacts'/f'{k}.svg').read_text(),'doc':d,
  'words':'\n'.join(c['id']+' = '+c['word'] for c in d['curves']),
  'summary':{'surface':r['surface'],'seam_words':{a:v['seam_word'] for a,v in r['curves'].items()},
  'regions':[{q:v[q] for q in ['genus','boundary_components','normalized_disk','embedded_closed_disk']} for v in r['regions']]}}
options=''.join(f'<option value="{k}">{html.escape(v[0])}</option>' for k,v in labels.items())
page='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>固定曲面上の経路保存・描画仕様</title><style>
:root{--ink:#172434;--muted:#516274;--line:#dce3ec;--paper:#f3f6fa;--accent:#185c88;--teal:#126957;--amber:#825715}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.8 system-ui,-apple-system,"Noto Sans JP","Yu Gothic",sans-serif}header,main,footer{max-width:1240px;margin:auto;padding:0 32px}nav{display:flex;gap:24px;align-items:center;padding:20px 0;border-bottom:1px solid var(--line);font-size:13px}nav strong{margin-right:auto;letter-spacing:.04em}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}.hero{padding:54px 0 32px;display:grid;grid-template-columns:1.5fr 1fr;gap:40px}.eyebrow{font-size:12px;color:var(--teal);letter-spacing:.14em;font-weight:750}h1{font-size:clamp(30px,3.5vw,46px);line-height:1.4;margin:12px 0 20px;letter-spacing:-.035em}h2{font-size:25px;margin:0 0 20px}h3{font-size:18px;margin:0 0 12px}.lead{color:var(--muted);max-width:700px;margin:0}code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}code{font-size:.88em}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.65;background:#edf1f6;padding:18px;border-radius:8px;max-height:380px;overflow:auto}.card{background:white;border:1px solid var(--line);border-radius:14px;padding:25px}.status{align-self:start}.stats{display:flex;gap:30px;margin:12px 0 18px}.number{font-size:38px;font-weight:750;line-height:1.2}.caption{font-size:12px;color:var(--muted)}.pill{display:inline-block;font-size:12px;border-radius:40px;padding:4px 12px;margin:3px 2px 3px 0;background:#e4f2ec;color:var(--teal)}.warn{background:#fcf1d8;color:var(--amber)}section{margin:24px 0 48px}.pipeline{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.step{border-top:4px solid var(--accent);padding:20px;background:white;border-radius:8px}.step .caption{line-height:1.65}.index{font-size:12px;color:var(--accent);font-weight:750;margin-bottom:12px}.viewer-head{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}select,button{padding:11px 14px;border-radius:8px;border:1px solid #afbdcd;background:white;color:var(--ink);font:inherit;font-size:14px;cursor:pointer}.viewer-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:25px}.figure{background:white;border-radius:12px;border:1px solid var(--line);overflow:hidden;padding:10px;min-height:460px}.figure svg{width:100%;max-height:530px;display:block}.hide-mesh .figure .mesh{display:none}.hide-labels .figure .label{display:none}.figure-tools{display:flex;gap:22px;font-size:13px;padding:8px 16px}.description{color:var(--muted);font-size:14px;margin:10px 0 18px}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:13px 15px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:12px;background:#f7f9fb}.callout{border-left:4px solid var(--amber);background:#fff8e9;padding:18px 22px;margin-top:20px;font-size:14px}details{margin:12px 0;border-bottom:1px solid var(--line);padding:10px 0}summary{font-weight:650;cursor:pointer}details p{font-size:14px;color:var(--muted)}footer{padding-bottom:40px;font-size:12px;color:var(--muted)}.buttons{display:flex;gap:10px;flex-wrap:wrap}.small{font-size:13px;color:var(--muted)}@media(max-width:850px){.hero,.viewer-grid,.two{grid-template-columns:1fr}.pipeline{grid-template-columns:1fr 1fr}header,main,footer{padding-left:18px;padding-right:18px}nav{gap:12px}nav strong{display:none}.viewer-head{align-items:stretch;flex-direction:column}.figure{min-height:300px}}
</style></head><body class="hide-mesh"><header><nav><strong>HEEGAARD · MARKED SURFACE · EXECUTABLE SPECIFICATION</strong><a href="#design">構造</a><a href="#examples">実例</a><a href="#guarantees">保証</a><a href="#install">据付け</a></nav>
<div class="hero"><div><div class="eyebrow">曲面・曲線・交点・領域を同時に保存する</div><h1>経路を、<br>描画器に決めさせない。</h1><p class="lead">固定された曲面の細分に図式を埋め込み、記号列で辺をたどる。見た目を変えるときも、曲線だけでなく細分全体を運ぶ。教科書のbigonや無交点の入れ子を省略しない。</p></div><div class="card status"><h3>検証の現在地</h3><div class="stats"><div><div class="number">36</div><div class="caption">参照実装テスト通過</div></div><div><div class="number">12</div><div class="caption">厳密描画の検証例</div></div></div><span class="pill">Python 実行済み</span><span class="pill warn">Julia 未実行</span><span class="pill warn">既存アプリ 未接続</span><p class="small">Juliaネイティブ実装と照合テストを同梱。既存の未コミット作業ツリーは取得していない。</p><a href="artifacts/verification-status.json">機械可読な検証状態 →</a></div></div></header>
<main><section id="design"><h2>数学データから描画まで</h2><div class="pipeline"><div class="step"><div class="index">MARKING</div><h3>基準曲面</h3><div class="caption">名前付き円板・向き・side貼合せ・真の境界。genusだけでは済ませない。</div></div><div class="step"><div class="index">EMBEDDING</div><h3>図式の埋込み</h3><div class="caption">各円板の全細分。曲線の辺語、交点ID、region witnessを保持する。</div></div><div class="step"><div class="index">REALIZATION</div><h3>既存の辺を実現</h3><div class="caption">境界固定の厳密な有理数座標。経路探索を再実行しない。</div></div><div class="step"><div class="index">CERTIFICATE</div><h3>検査後だけ表示</h3><div class="caption">全三角形・全辺を検査。SVGの小数化後も中心線の埋込みを再検査する。</div></div></div></section>
<section id="examples"><div class="viewer-head"><h2 style="margin:0">実行済みの経路を確認</h2><select id="model">OPTIONS</select></div><div class="viewer-grid"><div><div class="figure" id="figure"></div><div class="figure-tools"><label><input type="checkbox" id="mesh"> 補助細分を表示</label><label><input type="checkbox" id="labels" checked> 頂点ラベル</label></div><p class="small">円板の外周は基準chartの切断境界。円環はeast↔west、トーラスはさらにnorth↔southを逆向きに貼る。局所頂点名の一致ではなく、保存されたgate対応で継続する。</p></div><div><h3 id="title"></h3><p class="description" id="description"></p><div class="caption">実際に保存されている経路語</div><pre id="words"></pre><details><summary>seam語・領域の判定を見る</summary><pre id="summary"></pre></details><button id="save">この例の数学JSONを保存</button></div></div></section>
<section id="guarantees"><h2>保証することと、保証しないこと</h2><div class="two"><div class="card"><h3>同じコードを描き直しても変わらない</h3><p class="small">固定marking、side上の順序・parameter、円板全体の細分が同じなら、適合する実現は境界固定の円板同位で結べる。貼合せ後も同じ曲面上の図式全体の同位になる。</p><pre>有効なコード\n  └─ 一つの marked diagram isotopy class\n       ├─ 適合する描画 A\n       └─ 適合する描画 B</pre></div><div class="card"><h3>同位類ごとの正規形ではない</h3><p class="small">異なる細分が同じ図式を表すことはある。文書hashは同位類hashではない。個別曲線のnormal座標と、交点を保存する図式全体の表現は別。</p><pre>representation hash ≠ isotopy invariant\n\n幾何的なD ≠ Koda joining disk\n\n開円板の領域 ≠ 閉包が埋込み円板</pre></div></div><div class="callout">本ページの図は参照実装が実際に出力したSVG。任意の教科書画像から自動抽出した図でも、既存Poincaréの固定経路を復元した図でもない。ブラウザの画素化とstroke幅は数学的中心線の認証対象外。</div></section>
<section id="install"><h2>Codexへの据付けパッケージ</h2><div class="card"><table><thead><tr><th>層</th><th>同梱物</th><th>状態</th></tr></thead><tbody><tr><td>意味・仕様</td><td><a href="docs/SPECIFICATION_JA.md">詳細仕様</a> / <a href="docs/PROOFS_JA.md">証明と仮定</a></td><td>記述済み。形式証明ではない</td></tr><tr><td>Julia</td><td><code>src/MarkedSurfaceDiagrams.jl</code> / <code>src/builders.jl</code></td><td>実装済み・未実行</td></tr><tr><td>参照実装</td><td><code>tools/reference.py</code> / <code>test/test_reference.py</code></td><td>36試験通過</td></tr><tr><td>言語間照合</td><td><code>test/runtests.jl</code> / <code>test/expected.toml</code></td><td>期待値生成済み・Julia照合は未実行</td></tr><tr><td>既存アプリ</td><td><a href="docs/CODEX_HANDOFF.md">据付け指示</a> / <a href="docs/MIGRATION_JA.md">旧core移行</a></td><td>接続契約を記述。未接続</td></tr></tbody></table><pre>julia --startup-file=no test/runtests.jl\njulia --startup-file=no examples/author_annulus.jl\n\n# 実行済み参照経路\npython tools/verify.py</pre><p class="small">旧coreの情報不足を任意routingで補わない。旧viewの見た目へ戻す場合も、同じmarkingを保つ明示的なPL輸送を要求する。</p></div></section>
<section><h2>設計上の境界</h2><details><summary>meridian / longitudeやLickorishの曲線は使えるか？</summary><p>入力側の基準・操作語として使える。ただし、その語から図式全体の細分へコンパイルし、保存後の描画器は経路を選び直さない。一般twist語コンパイラは今回の実装範囲外。</p></details><details><summary>なぜ全体の細分が必要か？</summary><p>同じ交点列でも、補領域や入れ子、基準穴の回り方を落とす表現がある。ambient disk全体を持てば、曲線が存在しない側の情報も保存される。</p></details><details><summary>bigonの削除は見た目の最適化ではないのか？</summary><p>交点を固定した図式全体のambient isotopyでは、二重点を消せない。bigon除去を数学操作として使うときは、前後の図式を別のrewriteとして扱う。</p></details></section></main>
<footer>数学的参照：Ayaz–Kegel–Mohnkeのnormal curves、Farb–MargalitのAlexander lemma/method、Tutte型実現、Kodaのjoining条件。出典と今回独自の証明は <a href="docs/PROOFS_JA.md">PROOFS_JA.md</a> に分離して記載。<br>固定曲面上の忠実な表現と描画を実装し、一般同位判定・Lean形式化・既存配置の意味の自動復元は別の課題として残す。</footer>
<script>const models=MODELDATA;const select=document.getElementById('model');function render(){const m=models[select.value];document.getElementById('figure').innerHTML=m.svg;document.getElementById('title').textContent=m.title;document.getElementById('description').textContent=m.description;document.getElementById('words').textContent=m.words;document.getElementById('summary').textContent=JSON.stringify(m.summary,null,2)}select.addEventListener('change',render);document.getElementById('mesh').addEventListener('change',e=>document.body.classList.toggle('hide-mesh',!e.target.checked));document.getElementById('labels').addEventListener('change',e=>document.body.classList.toggle('hide-labels',!e.target.checked));document.getElementById('save').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(models[select.value].doc,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=select.value+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)};render();</script></body></html>'''
page=page.replace('OPTIONS',options).replace('MODELDATA',json.dumps(models,ensure_ascii=False).replace('</',r'<\/'))
(ROOT/'overview.html').write_text(page,encoding='utf8')
print(ROOT/'overview.html')
